class QueryBuilder {
  constructor() { this._parts = []; }
  select(cols) { this._parts.push(`SELECT ${cols}`); return this; }
  from(table) { this._parts.push(`FROM ${table}`); return this; }
  where(cond) { this._parts.push(`WHERE ${cond}`); return this; }
