class Leaf {
  constructor(val) { this.val = val; }
  sum() { return this.val; }
}

class Composite {
  constructor() { this.children = []; }
  add(child) { this.children.push(child); return this; }
  sum() { return this.children.reduce((a, c) => a + c.sum(), 0); }
}

const tree = new Composite()
  .add(new Leaf(1))
  .add(new Composite().add(new Leaf(2)).add(new Leaf(3)));
console.log(tree.sum());

