class Handler {
  setNext(handler) { this._next = handler; return handler; }
  handle(req) { return this._next?.handle(req); }
}

class AuthHandler extends Handler {
  handle(req) {
    if (!req.token) return 'Unauthorized';
    return super.handle(req);
  }
}

class DataHandler extends Handler {
  handle(req) { return 'data for ' + req.userId; }
}

const auth = new AuthHandler();
auth.setNext(new DataHandler());
console.log(auth.handle({ token: 'abc', userId: 1 }));
console.log(auth.handle({ userId: 1 }));

class EventBus {
  constructor() { this._handlers = {}; }
  subscribe(event, fn) {
    (this._handlers[event] ??= []).push(fn);
  }
  publish(event, data) {
    (this._handlers[event] ?? []).forEach(fn => fn(data));
  }
}

const bus = new EventBus();
bus.subscribe('login', user => console.log('logged in:', user));
bus.publish('login', 'Alice');

